125	    /**
126	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
127	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
128	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
129	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
130	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
131	     */
132	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
