313	            if (pet != null) {
314	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
315	            }
316	        }
317	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
318	    }
319	
320	    /**
321	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
322	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
323	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
324	     *
325	     * @param ownerFieldsDto the submitted owner fields
326	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
327	     *                                     name of every offending field
328	     */
329	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
330	        List<String> missingFields = new ArrayList<>();
331	        if (isBlank(ownerFieldsDto.getFirstName())) {
332	            missingFields.add("firstName");
333	        }
334	        if (isBlank(ownerFieldsDto.getLastName())) {
335	            missingFields.add("lastName");
336	        }
337	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
338	            missingFields.add("address");
339	        }
340	        if (isBlank(ownerFieldsDto.getCity())) {
341	            missingFields.add("city");
342	        }
343	        if (isBlank(ownerFieldsDto.getTelephone())) {
344	            missingFields.add("telephone");
345	        }
346	        if (!missingFields.isEmpty()) {
347	            throw new InvalidOwnerFieldsException(missingFields);
348	        }
349	    }
350	
351	    private boolean isBlank(String value) {
352	        return value == null || value.isBlank();
353	    }
354	
355	    /**
356	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
357	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
358	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
359	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
360	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
361	     * The returned value is stored and returned unchanged.
362	     *
363	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
364	     * @param region   the owner's region derived from its city
365	     * @return the postcode to store, or {@code null} if none was supplied
366	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
367	     *                                     out of range for the city's region, yielding a 400 response
368	     */
369	    private String validatePostcode(String postcode, String region) {
370	        if (postcode == null) {
371	            return null;
372	        }
373	        if (!postcode.matches("[0-9]{4}")) {
374	            throw new InvalidOwnerFieldsException(List.of("postcode"));
375	        }
376	        int[] range = REGION_POSTCODES.get(region);
377	        if (range != null) {
378	            int value = Integer.parseInt(postcode);
379	            if (value < range[0] || value > range[1]) {
380	                throw new InvalidOwnerFieldsException(List.of("postcode"));
381	            }
382	        }
383	        return postcode;
384	    }
385	
386	    /**
387	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
388	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
389	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
390	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
391	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
392	     *
393	     * @param telephone the raw telephone value submitted by the client
394	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
395	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
396	     *                                     400 response
397	     */
398	    private String normalizeTelephone(String telephone) {
399	        String e164 = toE164(telephone);
400	        if (e164 == null) {
401	            throw new InvalidOwnerFieldsException(List.of("telephone"));
402	        }
403	        return e164;
404	    }
405	
406	    /**
407	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
408	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
409	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
410	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
411	     * and when the supplied country code is one with a known national-number length
412	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
413	     * number must have exactly that many digits.
414	     *
415	     * @param telephone the raw telephone value, possibly {@code null}
416	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
417	     */
418	    private String toE164(String telephone) {
419	        if (telephone == null) {
420	            return null;
421	        }
422	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
423	        boolean hasPlus = cleaned.startsWith("+");
424	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
425	        String nationalSignificant = hasPlus
426	            ? digits
427	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
428	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
429	            return null;
430	        }
431	        if (!hasValidNationalNumberLength(nationalSignificant)) {
432	            return null;
433	        }
434	        return "+" + nationalSignificant;
435	    }
436	
437	    /**
438	     * Checks the national-number length of an E.164 number (country code plus national significant
439	     * digits, no leading {@code '+'}) against the per-country requirement in
440	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
441	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
442	     * country code is not listed carries no per-country length requirement and is accepted.
443	     *
444	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
445	     *                            leading {@code '+'}
446	     * @return {@code true} if the national-number length is correct for the country code, or the
447	     *         country code has no listed requirement; {@code false} otherwise
448	     */
449	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
450	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
451	            .filter(nationalSignificant::startsWith)
452	            .max(Comparator.comparingInt(String::length))
453	            .orElse(null);
454	        if (countryCode == null) {
455	            return true;
456	        }
457	        int nationalLength = nationalSignificant.length() - countryCode.length();
458	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
459	    }
460	
461	    /**
462	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
463	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
464	     * returned value is that address lower-cased.
465	     *
466	     * @param email the raw email value submitted by the client, or {@code null} if omitted
467	     * @return the lower-cased email, or {@code null} if none was supplied
468	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
469	     *                                     yielding a 400 response
470	     */
471	    private String normalizeEmail(String email) {
472	        if (email == null) {
473	            return null;
474	        }
475	        if (!EMAIL_PATTERN.matcher(email).matches()) {
476	            throw new InvalidOwnerFieldsException(List.of("email"));
477	        }
478	        return email.toLowerCase(Locale.ROOT);
479	    }
480	
481	    /**
482	     * Counts the existing owners that, before this create, already share the given first name and
483	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
484	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
485	     * been saved yet, so it is never included in the count.
486	     *
487	     * @param firstName the first name of the owner being created
488	     * @param lastName  the last name of the owner being created
489	     * @return the number of existing owners sharing both names
490	     */
491	    private int countNamesakes(String firstName, String lastName) {
492	        String normalizedFirstName = normalizeForComparison(firstName);
493	        String normalizedLastName = normalizeForComparison(lastName);
494	        return (int) this.clinicService.findAllOwners().stream()
495	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
496	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
497	            .count();
498	    }
499	
500	    /**
501	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
502	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
503	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
504	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
505	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
506	     * same postcode region, telephone and last name always yield the same customer code.
507	     *
508	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
509	     * @param telephone the owner's normalized (E.164) telephone
510	     * @param lastName  the owner's last name
511	     * @return the formatted customer code
512	     */
513	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
514	        String region = regionForPostcode(postcode);
515	        String hash8 = hash8(telephone + lastName);
516	        return region + "-" + hash8;
517	    }
518	
519	    /**
520	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
521	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
522	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
523	     * {@code <REGION>} segment baked into the {@code customerCode}.
524	     *
525	     * @param postcode the owner's postcode, or {@code null}
526	     * @return the region code, or {@code 'UNKNOWN'}
527	     */
528	    private String regionForPostcode(String postcode) {
529	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
530	            return "UNKNOWN";
531	        }
532	        int value = Integer.parseInt(postcode);
533	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
534	            int[] range = entry.getValue();
535	            if (value >= range[0] && value <= range[1]) {
536	                return entry.getKey();
537	            }
538	        }
539	        return "UNKNOWN";
540	    }
541	
542	    /**
543	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
544	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
545	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
546	     * region.
547	     *
548	     * @param city the owner's city
549	     * @return the region code, or {@code 'UNKNOWN'}
550	     */
551	    private String regionForCity(String city) {
552	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
553	    }
554	
555	    /**
556	     * Returns the first eight upper-cased hex characters of the SHA-256 digest of the given input,
557	     * used as the {@code <HASH8>} segment of a {@code customerCode}.
558	     *
559	     * @param input the value to hash
560	     * @return the first eight upper-cased hex characters of its SHA-256 digest
561	     */
562	    private String hash8(String input) {
563	        try {
564	            byte[] digest = MessageDigest.getInstance("SHA-256")
565	                .digest(input.getBytes(StandardCharsets.UTF_8));
566	            StringBuilder hex = new StringBuilder(digest.length * 2);
567	            for (byte b : digest) {
568	                hex.append(String.format("%02x", b));
569	            }
570	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
571	        } catch (NoSuchAlgorithmException e) {
572	            throw new IllegalStateException("SHA-256 algorithm not available", e);
573	        }
574	    }
575	
576	    /**
577	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
578	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
579	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
580	     * has not been saved yet, so it is never included in the count.
581	     *
582	     * @param city the city of the owner being created
583	     * @return the number of existing owners in that city
584	     */
585	    private int countOwnersInCity(String city) {
586	        String normalizedCity = normalizeForComparison(city);
587	        return (int) this.clinicService.findAllOwners().stream()
588	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
589	            .count();
590	    }
591	
592	    /**
593	     * Rejects creation of an owner whose city already contains the maximum number of owners
594	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
595	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
596	     *
597	     * @param city the city of the owner being created
598	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
599	     *                                      owners, yielding a 409 Conflict response
600	     */
601	    private void rejectCityAtCapacity(String city) {
602	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
603	            throw new OwnerCityAtCapacityException(city);
604	        }
605	    }
606	
607	    /**
608	     * Rejects creation of an owner once the given business day has already reached its daily quota
609	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
610	     * being that day — the adjusted business day the owner being created will carry — so the quota
611	     * applies per business day. The owner being created has not been saved yet, so it is never
612	     * included in the count.
613	     *
614	     * @param registrationDate the adjusted business-day registration date of the owner being created
615	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
616	     *                                         carry that registration date, yielding a
617	     *                                         429 Too Many Requests response
618	     */
619	    private void rejectDailyLimitReached(LocalDate registrationDate) {
620	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
621	            throw new DailyOwnerLimitReachedException(registrationDate);
622	        }
623	    }
624	
625	    /**
626	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
627	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
628	     *
629	     * @param registrationDate the business day to count owners for
630	     * @return the number of existing owners registered on that day
631	     */
632	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
633	        return this.clinicService.findAllOwners().stream()
634	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
635	            .count();
636	    }
637	
638	    /**
639	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
640	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
641	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
642	     * otherwise.
643	     *
644	     * @param ownerDto the owner response to flag
645	     */
646	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
647	        LocalDate today = toBusinessDay(LocalDate.now());
648	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
649	    }
650	
651	    /**
652	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
653	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
654	     * applies to the effective registration date whether it was supplied in the request or defaulted
655	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
656	     * feeds every value derived from it (such as the membership number's year segment and the daily
657	     * create-limit's per-day bucket).
658	     *
659	     * @param date the effective registration date, supplied or defaulted
660	     * @return the same date when it is a weekday, otherwise the next Monday
661	     */
662	    private LocalDate toBusinessDay(LocalDate date) {
663	        LocalDate adjusted = date;
664	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
665	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
666	            adjusted = adjusted.plusDays(1);
667	        }
668	        return adjusted;
669	    }
670	
671	    /**
672	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
673	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
674	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
675	     * separate telephone, email and household checks are all expressed through it. Because the
676	     * telephone is part of the key, two members of the same household (same {@code householdId})
677	     * with different telephones have different identity keys and are both allowed; only a whole-key
678	     * match is a duplicate. The owner being created already carries its normalized telephone,
679	     * email and (if any) household id, and existing owners store the same normalized forms, so the
680	     * keys are compared directly.
681	     *
682	     * @param owner the owner being created, with its telephone, email and household id already set
683	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
684	     *                                         yielding a 409 Conflict response
685	     */
686	    private void rejectDuplicateIdentity(Owner owner) {
687	        String identityKey = owner.getIdentityKey();
688	        boolean inUse = this.clinicService.findAllOwners().stream()
689	            .map(Owner::getIdentityKey)
690	            .anyMatch(identityKey::equals);
691	        if (inUse) {
692	            throw new DuplicateOwnerIdentityException(identityKey);
693	        }
694	    }
695	
696	    /**
697	     * Finds every existing owner belonging to the household identified by the given last name and
698	     * address — that is, the owners the {@code sharesHousehold} opt-in joins. Both the last name and
699	     * the address are compared case-insensitively with surrounding and internal whitespace collapsed,
700	     * so values that differ only in letter case or spacing still match. This definition of household
701	     * membership is used by {@link #assignHousehold}.
702	     *
703	     * @param lastName the last name of the owner being created
704	     * @param address  the address of the owner being created
705	     * @return the existing owners in that household, or an empty list if there are none
706	     */
707	    private List<Owner> findHouseholdMembers(String lastName, String address) {
708	        String normalizedLastName = normalizeForComparison(lastName);
709	        String normalizedAddress = normalizeAddress(address);
710	        return this.clinicService.findAllOwners().stream()
711	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
712	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
713	            .toList();
714	    }
715	
716	    /**
717	     * Enrolls a newly created owner into the household of any existing owner that shares its last
718	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
719	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
720	     * whitespace. When at least one such owner already exists, every member of the household — the
721	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
722	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
723	     * and address is created and back-filled onto the existing members. When no owner yet lives at
724	     * that address under the same last name no identifier is assigned and the owner is created alone.
725	     *
726	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
727	     * @param lastName the last name of the owner being created
728	     * @param address  the address of the owner being created
729	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
730	     */
731	    private String assignHousehold(Owner newOwner, String lastName, String address) {
732	        List<Owner> members = findHouseholdMembers(lastName, address);
733	        if (members.isEmpty()) {
734	            return null;
735	        }
736	        String householdId = members.stream()
737	            .map(Owner::getHouseholdId)
738	            .filter(existing -> existing != null && !existing.isBlank())
739	            .findFirst()
740	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
741	        for (Owner member : members) {
742	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
743	                member.setHouseholdId(householdId);
744	                this.clinicService.saveOwner(member);
745	            }
746	        }
747	        newOwner.setHouseholdId(householdId);
748	        return householdId;
749	    }
750	
751	    /**
752	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
753	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
754	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
755	     * same identifier, so members of one household share a single value.
756	     *
757	     * @param normalizedLastName the household's last name, already normalized for comparison
758	     * @param normalizedAddress  the household's address, already normalized for comparison
759	     * @return the derived household identifier
760	     */
761	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
762	        try {
763	            byte[] digest = MessageDigest.getInstance("SHA-256")
764	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
765	            StringBuilder hex = new StringBuilder(digest.length * 2);
766	            for (byte b : digest) {
767	                hex.append(String.format("%02x", b));
768	            }
769	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
770	        } catch (NoSuchAlgorithmException e) {
771	            throw new IllegalStateException("SHA-256 algorithm not available", e);
772	        }
773	    }
774	
775	    /**
776	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
777	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
778	     * the result is lower-cased.
779	     *
780	     * @param value the value to normalize, possibly {@code null}
781	     * @return the normalized value, or an empty string if {@code value} is {@code null}
782	     */
783	    private String normalizeForComparison(String value) {
784	        if (value == null) {
785	            return "";
786	        }
787	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
788	    }
789	
790	    /**
791	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
792	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
793	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
794	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
795	     * This normalized value is what gets stored and returned, and it is the form every address
796	     * comparison (household duplicate detection and the shared household id) uses.
797	     *
798	     * @param address the raw address value submitted by the client, possibly {@code null}
799	     * @return the normalized address, or an empty string if {@code address} is {@code null}
800	     */
801	    private String normalizeAddress(String address) {
802	        if (address == null) {
803	            return "";
804	        }
805	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
806	        if (collapsed.isEmpty()) {
807	            return collapsed;
808	        }
809	        String[] tokens = collapsed.split(" ");
810	        StringBuilder normalized = new StringBuilder(collapsed.length());
811	        for (int i = 0; i < tokens.length; i++) {
812	            if (i > 0) {
813	                normalized.append(' ');
814	            }
815	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
816	        }
817	        return normalized.toString();
818	    }
819	}
